def parse_options(
    args: List[str] | None = None,
    config: bool = True,
    rootdir: Path = CURDIR,
    **overrides: Any,
) -> Namespace:
    """Parse options from command line and configuration files."""
    parser = setup_parser()
    actions = {action.dest: action for action in parser._actions}  # pylint: disable=protected-access

    options = parser.parse_args(args or [])
    options.file_params = {}
    options.linters_params = {}

    if config:
        cfg = get_config(options.options, rootdir=rootdir)
        for raw_opt, val in cfg.default.items():
            opt = normalize_option_name(raw_opt)
            LOGGER.info("Find option %s (%s)", opt, val)
            passed_value = getattr(options, opt, _Default())
            if isinstance(passed_value, _Default):
                if opt == "paths":
                    if isinstance(val, str):
                        val = val.split()
                    elif not isinstance(val, list):
                        val = list(val)
                if opt == "skip":
                    if not isinstance(val, str):
                        val = ",".join(str(item) for item in val)
                    val = fix_pathname_sep(val)
                setattr(options, opt, _Default(val))

        for section_name, section_options in cfg.sections.items():
            if section_name == cfg.default_section:
                continue

            name = section_name
            if name.startswith(f"{DEFAULT_SECTION}:"):
                name = name[len(DEFAULT_SECTION) + 1 :]

            normalized = _normalize_section_options(section_options.items())
            if name in LINTERS:
                options.linters_params[name] = normalized
                continue

            mask = re.compile(fnmatch.translate(fix_pathname_sep(name)))
            options.file_params[mask] = normalized

    for opt, val in overrides.items():
        setattr(options, normalize_option_name(opt), process_value(actions, normalize_option_name(opt), val))

    for name in list(options.__dict__):
        value = getattr(options, name)
        if isinstance(value, _Default):
            setattr(options, name, process_value(actions, name, value.value))

    if options.concurrent and "pylint" in options.linters:
        LOGGER.warning("Can't parse code asynchronously with pylint enabled.")
        options.concurrent = False

